def submit_registration(saved_page: JourneyBrowserPage) -> JourneyBrowserPage:
    """Click the Create conference workspace button to submit the registration form."""
    page = open_page(saved_page)
    timeout_ms = 30000

    def unique_email(prefix: str) -> str:
        return _unique_email(prefix)

    page.click('[data-testid="create-workspace"]', timeout=timeout_ms)
    page.wait_for_load_state('networkidle', timeout=timeout_ms)
    page.wait_for_load_state("load", timeout=timeout_ms)
    _assert_page_state(page, expected_path='/', expected_title='MemosConf Registration Ops')
    return page


@journey
def explored_agentic_loop_journey() -> None:
    open_memosconf_registration_ops_page = step(open_memosconf_registration_ops)
    if branch(replay_from=open_memosconf_registration_ops_page):
        fill_organizer_name_page = step(fill_organizer_name, open_memosconf_registration_ops_page)
    elif branch(replay_from=open_memosconf_registration_ops_page):
        fill_organizer_email_page = step(fill_organizer_email, open_memosconf_registration_ops_page)
    elif branch(replay_from=open_memosconf_registration_ops_page):
        fill_workspace_name_page = step(fill_workspace_name, open_memosconf_registration_ops_page)
    elif branch(replay_from=open_memosconf_registration_ops_page):
        submit_registration_page = step(submit_registration, open_memosconf_registration_ops_page)
